// Generated by scripts/sync-examples.ts from scripts/example-app. Do not edit.
// Runs every Lucent end-to-end case through the native C++ modules and
// compares the output with the expected lines (the same code run as plain
// JavaScript on Node).
import { useEffect, useState } from "react";
import { Pressable, ScrollView, Text, View } from "react-native";
import { cases } from "../tests";
import { type CaseResult, runCase } from "./runCase";
import { styles } from "./styles";

export function TestsScreen() {
  const [results, setResults] = useState<CaseResult[]>([]);
  const [open, setOpen] = useState<string | null>(null);
  const [running, setRunning] = useState(false);

  async function runAll() {
    setRunning(true);
    setResults([]);
    const out: CaseResult[] = [];
    for (const c of cases) {
      out.push(await runCase(c));
      setResults([...out]);
    }
    setRunning(false);
  }

  useEffect(() => {
    void runAll();
  }, []);

  const passed = results.filter((r) => r.status === "pass").length;
  const done = !running && results.length === cases.length;

  return (
    <>
      <View style={styles.header}>
        <Text style={styles.title}>Lucent · C++ over JSI</Text>
        <Text style={styles.subtitle}>
          {results.length}/{cases.length} run · {passed} passed
        </Text>
        <Text
          testID="lucent-summary"
          style={[styles.summary, done && (passed === cases.length ? styles.ok : styles.bad)]}
        >
          {running
            ? "Running…"
            : done
              ? passed === cases.length
                ? "ALL PASSED"
                : `${cases.length - passed} FAILED`
              : ""}
        </Text>
        <Pressable
          disabled={running}
          onPress={runAll}
          style={({ pressed }) => [styles.button, (pressed || running) && styles.pressed]}
        >
          <Text style={styles.buttonText}>Run again</Text>
        </Pressable>
      </View>
      <ScrollView contentContainerStyle={styles.list}>
        {results.map((r) => (
          <Pressable
            key={r.name}
            onPress={() => setOpen(open === r.name ? null : r.name)}
            style={styles.row}
          >
            <Text style={styles.rowTitle}>
              {r.status === "pass" ? "✅" : "❌"} {r.name} <Text style={styles.ms}>{r.ms} ms</Text>
            </Text>
            {r.error ? <Text style={styles.error}>{r.error}</Text> : null}
            {open === r.name || r.status === "fail" ? (
              <View style={styles.details}>
                {r.expected.map((e, i) => {
                  const got = r.lines[i];
                  const same = got === e;
                  return (
                    <Text key={i} style={[styles.line, !same && styles.lineBad]}>
                      {same ? got : `expected: ${e}\n     got: ${got ?? "(nothing)"}`}
                    </Text>
                  );
                })}
                {r.lines.slice(r.expected.length).map((l, i) => (
                  <Text key={`x${i}`} style={[styles.line, styles.lineBad]}>
                    extra: {l}
                  </Text>
                ))}
              </View>
            ) : null}
          </Pressable>
        ))}
      </ScrollView>
    </>
  );
}
